"""UUIDv7 ids, generated by the client.

Time-ordered ids are what make `ORDER BY id DESC` mean "newest first" and keyset pagination
(`id < :before`) work without a second column, and they keep primary-key inserts appending
to the right edge of the index instead of landing on random pages.
"""

from __future__ import annotations

import secrets
import threading
import time
import uuid

_lock = threading.Lock()
_last_ms = 0
_sequence = 0


def uuid7() -> uuid.UUID:
    """An RFC 9562 UUIDv7, monotonic within this process.

    48 bits of Unix milliseconds, then a 12-bit sequence so ids minted in the same
    millisecond still sort in the order they were made, then 62 random bits.
    """
    global _last_ms, _sequence
    with _lock:
        now_ms = time.time_ns() // 1_000_000
        if now_ms > _last_ms:
            _last_ms = now_ms
            # Start low so a burst has room to count up before the sequence wraps.
            _sequence = secrets.randbits(10)
        else:
            _sequence += 1
            if _sequence > 0xFFF:
                # Sequence exhausted (or the clock stepped back): borrow the next
                # millisecond rather than ever issuing an id that sorts before the last.
                _last_ms += 1
                _sequence = 0
        timestamp, sequence = _last_ms, _sequence
    value = (
        (timestamp & 0xFFFF_FFFF_FFFF) << 80
        | 0x7 << 76
        | sequence << 64
        | 0b10 << 62
        | secrets.randbits(62)
    )
    return uuid.UUID(int=value)
